3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: grid;
13	    place-items: center;
14	    background: #eef0f3;
15	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
16	  }
17	  .calc {
18	    width: min(320px, 100vw - 32px);
19	    padding: 16px;
20	    border-radius: 20px;
21	    background: #1f2329;
22	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
23	  }
24	  .display {
25	    height: 80px;
26	    margin-bottom: 16px;
27	    padding: 0 12px;
28	    border-radius: 12px;
29	    background: #111418;
30	    color: #fff;
31	    font-size: 40px;
32	    display: flex;
33	    align-items: center;
34	    justify-content: flex-end;
35	    overflow: hidden;
36	    white-space: nowrap;
37	    font-variant-numeric: tabular-nums;
38	  }
39	  .keys {
40	    display: grid;
41	    grid-template-columns: repeat(4, 1fr);
42	    gap: 10px;
43	  }
44	  button {
45	    height: 60px;
46	    border: 0;
47	    border-radius: 12px;
48	    background: #3a4049;
49	    color: #fff;
50	    font: inherit;
51	    font-size: 22px;
52	    cursor: pointer;
53	  }
54	  button:hover { filter: brightness(1.15); }
55	  button:active { filter: brightness(0.9); }
56	  button:focus-visible { outline: 2px solid #8ab4ff; outline-offset: 2px; }
57	  .op { background: #f08c2e; }
58	  .op.active { background: #fff; color: #f08c2e; }
59	  .fn { background: #8a929c; color: #111; }
60	  .wide { grid-column: span 2; }
61	  .tape { margin-top: 16px; padding-top: 12px; border-top: 1px solid #3a4049; color: #fff; }
62	  .tape-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; color: #8a929c; font-size: 13px; }
63	  .tape-clear { height: auto; padding: 4px 10px; border-radius: 8px; background: transparent; color: #8ab4ff; font-size: 13px; }
64	  .tape-rows { list-style: none; margin: 0; padding: 0; max-height: 180px; overflow-y: auto; }
65	  .tape-row { display: flex; flex-direction: column; align-items: flex-end; padding: 6px 12px; font-variant-numeric: tabular-nums; }
66	  .tape-row + .tape-row { border-top: 1px solid #2b3037; }
67	  .tape-expr { color: #8a929c; font-size: 14px; overflow-wrap: anywhere; text-align: right; }
68	  .tape-result { font-size: 20px; }
69	</style>
70	</head>
71	<body>
72	<main class="calc">
73	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" role="status" aria-live="polite">0</div>
74	  <div class="keys">
75	    <button class="fn wide" data-testid="key-lparen" data-key="lparen" aria-label="open group">(</button>
76	    <button class="fn wide" data-testid="key-rparen" data-key="rparen" aria-label="close group">)</button>
77	    <button class="fn wide" data-testid="key-clear" data-key="clear">AC</button>
78	    <button class="fn" data-testid="key-sign" data-key="sign" aria-label="change sign">±</button>
79	    <button class="op" data-testid="key-div" data-key="div" aria-label="divide">÷</button>
80	    <button data-testid="key-7" data-key="7">7</button>
81	    <button data-testid="key-8" data-key="8">8</button>
82	    <button data-testid="key-9" data-key="9">9</button>
83	    <button class="op" data-testid="key-mul" data-key="mul" aria-label="multiply">×</button>
84	    <button class="op" data-testid="key-sub" data-key="sub" aria-label="subtract">−</button>
85	    <button data-testid="key-4" data-key="4">4</button>
86	    <button data-testid="key-5" data-key="5">5</button>
87	    <button data-testid="key-6" data-key="6">6</button>
88	    <button class="op" data-testid="key-add" data-key="add" aria-label="add">+</button>
89	    <button data-testid="key-1" data-key="1">1</button>
90	    <button data-testid="key-2" data-key="2">2</button>
91	    <button data-testid="key-3" data-key="3">3</button>
92	    <button class="wide" data-testid="key-0" data-key="0">0</button>
93	    <button data-testid="key-dot" data-key="dot" aria-label="decimal point">.</button>
94	    <button class="op" data-testid="key-equals" data-key="equals" aria-label="equals">=</button>
95	  </div>
96	  <section class="tape" data-testid="calc-tape" aria-label="History">
97	    <div class="tape-head">
98	      <span>History</span>
99	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
100	    </div>
101	    <ol class="tape-rows"></ol>
102	  </section>
103	</main>
104	<script>
105	// Pure calculator logic. State: acc (stored left operand), op (pending operator),
106	// entry (digits being typed, or null), value (the current number, never rounded),
107	// error (true after a division by zero; only clear leaves it), stack (saved acc/op of each
108	// open group), closed (true right after `)`: value is a finished group result, not an entry).
109	var OPS = {
110	  add: function (a, b) { return a + b; },
111	  sub: function (a, b) { return a - b; },
112	  mul: function (a, b) { return a * b; },
113	  div: function (a, b) { return a / b; }
114	};
115	
116	function initialState() {
117	  return { acc: null, op: null, entry: null, value: 0, error: false, stack: [], closed: false };
118	}
119	
120	function errorState(v) {
121	  return { acc: null, op: null, entry: null, value: v, error: true, stack: [], closed: false };
122	}
123	
124	function press(s, key) {
125	  if (key === 'clear') return initialState();
126	
127	  // In the error state every key except clear is ignored.
128	  if (s.error) return s;
129	
130	  if (/^[0-9]$/.test(key)) {
131	    var entry = s.entry === null || s.entry === '0' ? key : s.entry === '-0' ? '-' + key : s.entry + key;
132	    return { acc: s.acc, op: s.op, entry: entry, value: Number(entry), error: false, stack: s.stack, closed: false };
133	  }
134	
135	  if (key === 'dot') {
136	    var e = s.entry === null ? '0' : s.entry;
137	    if (e.indexOf('.') !== -1) return s;
138	    e += '.';
139	    return { acc: s.acc, op: s.op, entry: e, value: Number(e), error: false, stack: s.stack, closed: false };
140	  }
141	
142	  // Sign and percent act on the current entry. Right after an operator there is no
143	  // entry yet, so they start one from 0. After a result or a closed group they act on the value.
144	  if (key === 'sign' || key === 'percent') {
145	    if (s.entry === null && (!s.op || s.closed)) {
146	      var nv = key === 'sign' ? -s.value : s.value / 100;
147	      return { acc: s.acc, op: s.op, entry: null, value: nv, error: false, stack: s.stack, closed: s.closed };
148	    }
149	    var cur = s.entry === null ? '0' : s.entry;
150	    var ne = key === 'sign' ? (cur[0] === '-' ? cur.slice(1) : '-' + cur) : shiftDecimal(cur, -2);
151	    return { acc: s.acc, op: s.op, entry: ne, value: Number(ne), error: false, stack: s.stack, closed: false };
152	  }
153	
154	  if (key in OPS) {
155	    // Operator right after another operator replaces it.
156	    if (s.op && s.entry === null && !s.closed) return { acc: s.acc, op: key, entry: null, value: s.value, error: false, stack: s.stack, closed: false };
157	    // Immediate execution: finish the waiting operation first, strictly left to right,
158	    // no precedence. The display always shows a real running result.
159	    var v = s.op ? OPS[s.op](s.acc, s.value) : s.value;
160	    if (!isFinite(v)) return errorState(v);
161	    return { acc: v, op: key, entry: null, value: v, error: false, stack: s.stack, closed: false };
162	  }
163	
164	  // `(` saves the waiting operation and starts a fresh one inside the group. It only
165	  // makes sense where a number could start, so it is ignored after an entry or a group.
166	  if (key === 'lparen') {
167	    if (s.entry !== null || s.closed) return s;
168	    var frame = { acc: s.acc, op: s.op };
169	    return { acc: null, op: null, entry: null, value: 0, error: false, stack: s.stack.concat([frame]), closed: false };
170	  }
171	
172	  // `)` finishes the group like equals, then restores the saved operation with the group
173	  // result as its right operand. Without an open group it is ignored.
174	  if (key === 'rparen') {
175	    if (!s.stack.length) return s;
176	    var g = s.op ? OPS[s.op](s.acc, s.value) : s.value;
177	    if (!isFinite(g)) return errorState(g);
178	    var top = s.stack[s.stack.length - 1];
179	    return { acc: top.acc, op: top.op, entry: null, value: g, error: false, stack: s.stack.slice(0, -1), closed: true };
180	  }
181	
182	  if (key === 'equals') {
183	    // Equals closes any groups left open.
184	    while (s.stack.length) {
185	      s = press(s, 'rparen');
186	      if (s.error) return s;
187	    }
188	    if (!s.op) return { acc: null, op: null, entry: null, value: s.value, error: false, stack: [], closed: false };
189	    var r = OPS[s.op](s.acc, s.value);
190	    if (!isFinite(r)) return errorState(r);
191	    return { acc: null, op: null, entry: null, value: r, error: false, stack: [], closed: false };
192	  }
193	
194	  return s;
195	}
196	
197	// Moves the decimal point of an entry string by n places, exactly, with no float noise.
198	// shiftDecimal('50', -2) is '0.5'.
199	function shiftDecimal(entry, n) {
200	  var sign = entry[0] === '-' ? '-' : '';
201	  var parts = entry.slice(sign.length).split('.');
202	  var digits = parts[0] + (parts[1] || '');
203	  var pos = parts[0].length + n;
204	  var str = pos <= 0 ? '0.' + '0'.repeat(-pos) + digits
205	    : pos >= digits.length ? digits + '0'.repeat(pos - digits.length)
206	    : digits.slice(0, pos) + '.' + digits.slice(pos);
207	  if (str.indexOf('.') !== -1) str = str.replace(/0+$/, '').replace(/\.$/, '');
208	  str = str.replace(/^0+(?=\d)/, '');
209	  return sign + str;
210	}
211	
212	// Presentation only: at most 10 significant digits, no trailing zeros, no separators.
213	// Exponential notation only when the rounded magnitude is >= 1e10 or < 1e-9.
214	function formatNumber(x) {
215	  var m = Math.abs(x).toExponential(9).split('e');
216	  var digits = m[0].replace('.', '');
217	  var exp = Number(m[1]);
218	  var sign = x < 0 ? '-' : '';
219	  if (x !== 0 && (exp >= 10 || exp < -9)) {
220	    return sign + m[0].replace(/\.?0+$/, '') + 'e' + m[1];
221	  }
222	  var int = exp >= 0 ? digits.slice(0, exp + 1) : '0';
223	  var frac = (exp >= 0 ? digits.slice(exp + 1) : '0'.repeat(-exp - 1) + digits).replace(/0+$/, '');
224	  return (int === '0' && frac === '' ? '' : sign) + int + (frac ? '.' + frac : '');
225	}
226	
227	// Visible text: the entry exactly as typed, Error, or the value formatted at render time.
228	function displayText(s) {
229	  if (s.error) return 'Error';
230	  if (s.entry !== null) return s.entry;
231	  return formatNumber(s.value);
232	}
233	
234	// Expression for the tape, tracked beside press(): head (tokens before the current operand),
235	// operand (text of a finished group or a changed group, or null to use the entry or value),
236	// groups (heads saved by each open `(`).
237	var SYMBOLS = { add: '+', sub: '−', mul: '×', div: '÷' };
238	
239	function initialExpr() {
240	  return { head: [], operand: null, groups: [] };
241	}
242	
243	function operandText(s, t) {
244	  if (s.entry !== null) return s.entry.replace(/\.$/, '');
245	  if (t.operand !== null) return t.operand;
246	  return formatNumber(s.value);
247	}
248	
249	// Returns the expression after key moved state s to n, and the tape row
250	// ({ expr, value }) when equals completed a calculation.
251	function trackExpr(t, s, key, n) {
252	  if (key === 'clear' || n.error) return { expr: initialExpr(), row: null };
253	  if (n === s) return { expr: t, row: null };
254	  if (/^[0-9]$/.test(key) || key === 'dot') {
255	    return { expr: { head: t.head, operand: null, groups: t.groups }, row: null };
256	  }
257	  if (key === 'sign' || key === 'percent') {
258	    var o = null;
259	    if (s.entry === null && (!s.op || s.closed) && t.operand !== null) {
260	      o = key === 'percent' ? t.operand + '%' : t.operand[0] === '-' ? t.operand.slice(1) : '-' + t.operand;
261	    }
262	    return { expr: { head: t.head, operand: o, groups: t.groups }, row: null };
263	  }
264	  if (key in OPS) {
265	    var head = s.op && s.entry === null && !s.closed
266	      ? t.head.slice(0, -1).concat([SYMBOLS[key]])
267	      : t.head.concat([operandText(s, t), SYMBOLS[key]]);
268	    return { expr: { head: head, operand: null, groups: t.groups }, row: null };
269	  }
270	  if (key === 'lparen') {
271	    return { expr: { head: [], operand: null, groups: t.groups.concat([t.head]) }, row: null };
272	  }
273	  if (key === 'rparen') {
274	    var group = '(' + t.head.concat([operandText(s, t)]).join(' ') + ')';
275	    return { expr: { head: t.groups[t.groups.length - 1], operand: group, groups: t.groups.slice(0, -1) }, row: null };
276	  }
277	  if (key === 'equals') {
278	    // A bare number is not a calculation, so it adds no row.
279	    var calc = t.head.length || t.groups.length || t.operand !== null;
280	    while (s.stack.length) {
281	      var next = press(s, 'rparen');
282	      t = trackExpr(t, s, 'rparen', next).expr;
283	      s = next;
284	    }
285	    var row = calc ? { expr: t.head.concat([operandText(s, t)]).join(' '), value: n.value } : null;
286	    return { expr: initialExpr(), row: row };
287	  }
288	  return { expr: t, row: null };
289	}
290	
291	if (typeof document !== 'undefined') {
292	  var state = initialState();
293	  var expr = initialExpr();
294	  var tape = [];
295	  var tapeRows = document.querySelector('.tape-rows');
296	  var display = document.querySelector('[data-testid="calc-display"]');
297	  var opButtons = document.querySelectorAll('[data-key="add"],[data-key="sub"],[data-key="mul"],[data-key="div"]');
298	
299	  function render() {
300	    display.textContent = displayText(state);
301	    display.setAttribute('data-value', String(state.value));
302	    display.setAttribute('data-error', state.error ? 'true' : 'false');
303	    for (var i = 0; i < opButtons.length; i++) {
304	      var b = opButtons[i];
305	      b.classList.toggle('active', state.op === b.dataset.key && state.entry === null && !state.closed);
306	    }
307	  }
308	
309	  function renderTape() {
310	    tapeRows.textContent = '';
311	    for (var i = 0; i < tape.length; i++) {
312	      var li = document.createElement('li');
313	      li.className = 'tape-row';
314	      li.setAttribute('data-testid', 'tape-row');
315	      var ex = document.createElement('span');
316	      ex.className = 'tape-expr';
317	      ex.setAttribute('data-testid', 'tape-expr');
318	      ex.textContent = tape[i].expr;
319	      var res = document.createElement('span');
320	      res.className = 'tape-result';
321	      res.setAttribute('data-testid', 'tape-result');
322	      res.setAttribute('data-value', String(tape[i].value));
323	      res.textContent = formatNumber(tape[i].value);
324	      li.appendChild(ex);
325	      li.appendChild(res);
326	      tapeRows.appendChild(li);
327	    }
328	  }
329	
330	  function apply(key) {
331	    var next = press(state, key);
332	    var r = trackExpr(expr, state, key, next);
333	    state = next;
334	    expr = r.expr;
335	    if (r.row) {
336	      tape.unshift(r.row);
337	      renderTape();
338	    }
339	    render();
340	  }
341	
342	  document.querySelector('.keys').addEventListener('click', function (ev) {
343	    var btn = ev.target.closest('button');
344	    if (!btn) return;
345	    apply(btn.dataset.key);
346	  });
347	
348	  // Clearing the tape leaves the calculator and its display untouched.
349	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
350	    tape = [];
351	    renderTape();
352	  });
353	
354	  var KEYMAP = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul', '/': 'div',
355	    '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
356	  document.addEventListener('keydown', function (ev) {
357	    var key = /^[0-9]$/.test(ev.key) ? ev.key : KEYMAP[ev.key];
358	    if (!key || ev.ctrlKey || ev.metaKey || ev.altKey) return;
359	    ev.preventDefault();
360	    apply(key);
361	  });
362	
363	  render();
364	}
365	</script>
366	</body>
367	</html>
